<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/portal.php';
$q=$pdo->prepare('SELECT id,program_id FROM scholars WHERE user_id=?');$q->execute([$portalUser['id']]);$s=$q->fetch();$items=[];$reqs=[];
if($s){$q=$pdo->prepare('SELECT r.id,r.name,r.due_date,d.status,d.note,d.original_name FROM document_requirements r LEFT JOIN scholar_documents d ON d.requirement_id=r.id AND d.scholar_id=? WHERE r.program_id=? ORDER BY r.due_date');$q->execute([$s['id'],$s['program_id']]);$items=$q->fetchAll();$q=$pdo->prepare('SELECT id,name FROM document_requirements WHERE program_id=? ORDER BY name');$q->execute([$s['program_id']]);$reqs=$q->fetchAll();}
portalStart('My Documents','documents.php');if(!$s)portalNotice('Your account does not have a scholarship assignment yet.');
foreach($items as $d)echo '<div class="portal-panel"><h2>'.h($d['name']).'</h2><p>Due: '.h($d['due_date']??'Not set').' · Status: '.h($d['status']??'Missing').'</p><p>'.h($d['original_name']??'No file submitted').'</p>'.($d['note']?'<small>Reviewer note: '.h($d['note']).'</small>':'').'</div>';
if($s&&$reqs){echo '<div class="portal-panel"><h2>Upload required document</h2><form class="portal-form" method="post" action="../portal_action.php" enctype="multipart/form-data">'.csrf_field().'<input type="hidden" name="action" value="submit_document"><input type="hidden" name="back" value="documents.php"><label>Requirement<select name="requirement_id" required>';foreach($reqs as $r)echo '<option value="'.h($r['id']).'">'.h($r['name']).'</option>';echo '</select></label><label>File (PDF/JPG/PNG, max 5 MB)<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required></label><button class="portal-button">Upload</button></form></div>';}portalEnd();